// The gear catalog reader — ONE list of every wearable / holdable Chibi 2 model, old and new.
//
// PURE: no Three.js, no DOM. Tools and node tests read it; games use it to turn an item into a look; the Armory
// experiment lists and previews everything in it. The data is avatar-3d/data/gear-catalog.json, generated by
// tools/build-gear-catalog.mjs (never edited by hand). CHIBI2.md "Gear catalog" is the long form.
//
//   import { loadGearCatalog, applyGear } from '../../avatar-3d/js/gear-catalog.js';
//   const cat = await loadGearCatalog();
//   cat.find({ gameSlot: 'chest', archetype: 'plate', isNew: true })   // -> [ the Fluted Cuirass row ]
//   cat.forItem({ slot: 'weapon', subtype: 'wand', form: 'cone' })      // -> the Bellmouth Wand row
//   const avatar2 = applyGear(avatar, [cat.byId('g5_plate_cuirass'), cat.byId('g5_plate_gauntlets')]);
//
// A ROW names a Chibi 2 part by the avatar slot it goes in (`slot`) and, for the few parts that ride an extra
// field of a slot rather than its id, that `field`:
//     hands  -> avatar.top.gloves      = { id, color, color2 }
//     rings  -> avatar.accessory.ring  = { id, color, color2 }   (ring2: the other hand)
// Extra fields survive the shared 2D normaliser, which is why they are fields and not new top-level slots.

export const GAME_SLOTS = ['weapon', 'offhand', 'head', 'chest', 'legs', 'hands', 'feet', 'cape', 'necklace', 'ring', 'light', 'belt'];
export const ARCHETYPES = ['cloth', 'leather', 'mail', 'plate'];
export const ATTACK_FORMS = ['projectile', 'cone', 'area', 'beam', 'fork', 'shield'];
export const WEAPON_TYPES = ['dagger', 'sword', 'sword2h', 'axe', 'axe2h', 'mace', 'hammer', 'hammer2h', 'spear', 'polearm', 'javelin', 'bow', 'crossbow', 'wand', 'staff', 'quarterstaff', 'scepter', 'orb', 'tome'];
export const FOCUS_KINDS = ['tome', 'orb', 'relic', 'idol', 'ward', 'totem'];
export const SHIELD_KINDS = ['buckler', 'heater', 'kite', 'tower'];

/** An item base's armour weight (items.json `tier`) -> the catalog's archetype. */
export const ARCHETYPE_OF_TIER = { cloth: 'cloth', runed: 'cloth', light: 'leather', leather: 'leather', medium: 'mail', scaled: 'mail', mail: 'mail', heavy: 'plate', plate: 'plate' };
/** An item's weapon subtype (and whether it is two-handed) -> the catalog's weapon type. */
export function weaponTypeOf(item) {
  const sub = item?.subtype || item?.sub || item?.weaponType || item?.type;
  const two = !!(item?.twoHanded || item?.hands === 2);
  const base = item?.baseKey || item?.base || '';
  if (sub === 'staff') return /quarterstaff|bo\b|bostaff/.test(base) || item?.melee ? 'quarterstaff' : 'staff';
  if (sub === 'hammer' || sub === 'warhammer') return two ? 'hammer2h' : 'hammer';
  if (sub === 'sword') return two ? 'sword2h' : 'sword';
  if (sub === 'axe' || sub === 'battleaxe') return two ? 'axe2h' : 'axe';
  const same = { greatsword: 'sword2h', sword2h: 'sword2h', axe2h: 'axe2h', greataxe: 'axe2h', maul: 'hammer2h', halberd: 'polearm', glaive: 'polearm', sceptre: 'scepter', shortbow: 'bow', longbow: 'bow', rapier: 'sword', saber: 'sword', scimitar: 'sword', longsword: 'sword' };
  return same[sub] || (WEAPON_TYPES.includes(sub) ? sub : null);
}
/** Game equipment slot -> the game slot name the catalog uses. */
const SLOT_ALIAS = { mainhand: 'weapon', back: 'cape', cloak: 'cape', neck: 'necklace', amulet: 'necklace', ring2: 'ring', gloves: 'hands', boots: 'feet', helmet: 'head', body: 'chest', lantern: 'light' };

const clone = v => JSON.parse(JSON.stringify(v));

/**
 * The look for one row: `{ slot, part }` — `part` is what to put in (or, for a `field` row, merge INTO)
 * `avatar[slot]`. `opts`: color, color2 (default: the row's), quality (0-3: the detail a held thing earns),
 * and anything else to carry on the part (emblem, emblemColor…). `opts.hand: 'off'` puts a one-handed weapon
 * in the off hand; `opts.field: 'ring2'` puts a ring on the other hand.
 */
export function lookFor(row, opts = {}) {
  if (!row) return null;
  const { hand, field, ...rest } = opts;
  const body = { id: row.id };
  if (rest.color ?? row.color) body.color = rest.color ?? row.color;
  if (rest.color2 ?? row.color2) body.color2 = rest.color2 ?? row.color2;
  for (const [k, v] of Object.entries(rest)) if (v != null && k !== 'color' && k !== 'color2') body[k] = v;
  const slot = row.slot === 'held' && hand === 'off' && row.offhandToo ? 'offhand' : row.slot;
  const f = field || row.field;
  return { slot, part: f ? { [f]: body } : body, field: f || null };
}
/** The same as an avatar patch: `{ [slot]: part }`. */
export function lookPatch(row, opts = {}) { const l = lookFor(row, opts); return l ? { [l.slot]: l.part } : {}; }

/**
 * A new avatar wearing every row given (rows or ids; `catalog` is needed for ids). Each patch is merged ONE
 * level deep, so a glove merges into the top the avatar already wears instead of replacing it. Call it LAST —
 * after anything that replaces a whole slot (class-outfits.js tier2Dress replaces `decor`).
 * `optsById`: per-row look options, e.g. `{ g5_plate_cuirass: { color: '#c8a24a' } }`.
 */
export function applyGear(avatar, rowsOrIds, optsById = {}, catalog = null) {
  const out = clone(avatar || {});
  for (const item of rowsOrIds || []) {
    const row = typeof item === 'string' ? catalog?.byId(item) : item;
    if (!row) continue;
    const l = lookFor(row, optsById[row.id] || {});
    out[l.slot] = l.field ? { ...(out[l.slot] || {}), ...l.part } : { ...(row.slot === 'top' ? pick(out.top, ['gloves']) : row.slot === 'accessory' ? pick(out.accessory, ['ring', 'ring2']) : {}), ...l.part };
  }
  return out;
}
const pick = (o, keys) => Object.fromEntries(keys.filter(k => o && o[k] != null).map(k => [k, o[k]]));

/** Wrap a parsed gear-catalog.json. */
export function createGearCatalog(json) {
  const rows = json?.rows || [], index = new Map(rows.map(r => [r.id + '|' + r.slot, r])), first = new Map();
  for (const r of rows) if (!first.has(r.id)) first.set(r.id, r);
  const cat = {
    version: json?.version || 0, rows,
    /** A row by part id (and, where an id is both a held and an off-hand part, the avatar slot). */
    byId: (id, slot = null) => (slot ? index.get(id + '|' + slot) : null) || first.get(id) || null,
    /** Rows matching every field given. `isNew` true/false, `game` a game that draws it, `tag` one tag. */
    find({ kind, slot, field, gameSlot, type, archetype, form, element, hands, isNew, game, tag } = {}) {
      return rows.filter(r => (kind == null || r.kind === kind) && (slot == null || r.slot === slot) && (field === undefined || (r.field || null) === (field || null))
        && (gameSlot == null || r.gameSlot === gameSlot) && (type == null || r.type === type) && (archetype == null || r.archetype === archetype)
        && (form == null || r.form === form) && (element == null || r.element === element) && (hands == null || r.hands === hands)
        && (isNew == null || r.new === isNew) && (game == null || r.games.includes(game)) && (tag == null || r.tags.includes(tag)));
    },
    /**
     * The NEW model for a game item, or null (the game then keeps the look it already draws). Reads what an
     * item carries in any of the games: `slot`, `tier` (armour weight), `subtype` + `twoHanded`, `isShield` /
     * `isFocus` / `baseKey`, and `form` / `castForm` (the magic attack form) for wands, staves and foci.
     * An item may also just say which model it is: `item.look.g5` (or `item.g5`) = a catalog id.
     */
    forItem(item, { isNew = true } = {}) {
      if (!item) return null;
      const named = item.look?.g5 || item.g5;
      if (named) return cat.byId(named);
      const want = isNew == null ? {} : { isNew };
      const slot = SLOT_ALIAS[item.slot] || item.slot || (item.type === 'weapon' ? 'weapon' : null);
      const form = item.form || item.castForm || item.attackForm || null;
      const one = list => list[0] || null;
      if (item.type === 'weapon' || slot === 'weapon') {
        const type = weaponTypeOf(item);
        if (!type) return null;
        return (form && one(cat.find({ ...want, kind: 'weapon', type, form }))) || one(cat.find({ ...want, kind: 'weapon', type }));
      }
      if (slot === 'offhand') {
        const key = item.baseKey || item.base || item.subtype || '';
        if (item.isShield || item.isMagicShield || /shield|buckler|aegis|bulwark|targe|pavise/.test(key)) {
          const kind = /buckler|targe/.test(key) ? 'buckler' : /tower|pavise|bulwark|aegis_shield/.test(key) ? 'tower' : /kite|aegis/.test(key) ? 'kite' : 'heater';
          return one(cat.find({ ...want, type: 'shield', tag: 'shield:' + kind })) || one(cat.find({ ...want, type: 'shield' }));
        }
        if (/quiver/.test(key)) return one(cat.find({ ...want, type: 'quiver' }));
        if (/torch/.test(key)) return one(cat.find({ ...want, slot: 'offhand', type: 'torch' }));
        const focus = item.focus || (/grimoire|psalter|tome|book|folio/.test(key) ? 'tome' : /orb|glass/.test(key) ? 'orb' : /reliquar|relic|censer/.test(key) ? 'relic' : /effigy|idol|mask/.test(key) ? 'idol' : /ward|sigil/.test(key) ? 'ward' : /totem|antler/.test(key) ? 'totem' : null);
        return (form && one(cat.find({ ...want, type: 'focus', form }))) || (focus && one(cat.find({ ...want, type: 'focus', tag: 'focus:' + focus }))) || null;
      }
      if (['head', 'chest', 'legs', 'hands', 'feet'].includes(slot)) {
        const archetype = ARCHETYPE_OF_TIER[item.tier] || ARCHETYPE_OF_TIER[item.archetype] || null;
        return archetype ? one(cat.find({ ...want, kind: 'armour', gameSlot: slot, archetype })) : null;
      }
      if (slot === 'light') return one(cat.find({ ...want, gameSlot: 'light', slot: /torch/.test(item.subtype || '') ? 'offhand' : 'decor' })) || one(cat.find({ ...want, gameSlot: 'light' }));
      return GAME_SLOTS.includes(slot) ? one(cat.find({ ...want, gameSlot: slot })) : null;
    },
    lookFor, lookPatch,
    applyGear: (avatar, rowsOrIds, optsById) => applyGear(avatar, rowsOrIds, optsById, cat),
  };
  return cat;
}

let cached = null;
/** Load avatar-3d/data/gear-catalog.json (fetch in a browser, the file system under node). Cached. */
export async function loadGearCatalog(url = new URL('../data/gear-catalog.json', import.meta.url)) {
  if (cached && cached.url === String(url)) return cached.cat;
  const u = new URL(url, import.meta.url);
  let json;
  if (u.protocol === 'file:') { const { readFileSync } = await import('node:fs'); json = JSON.parse(readFileSync(u, 'utf8')); }
  else json = await (await fetch(u)).json();
  cached = { url: String(url), cat: createGearCatalog(json) };
  return cached.cat;
}
